#include<iostream>
int calculate(int base,int power)
{
    if(power==0)
    {
        return 1;
    }
    if(power%2==0)
    {
        int ans=calculate(base,power/2);
        return ans*ans;
    }
    else
    {
        power=power-1;
        int ans=calculate(base,power/2);
        return ans*ans*base;
    }
}
